private MediaPlayer player;private SolarAlarmWvPlayback wavpack;private MediaSession session;private AudioFocusRequest focus;private AudioManager audio;private long active=-1,token=0;private boolean restricted=false,verified=false;private int routeChecks=0;private SolarAlarmStore.Event activeEvent;private final Handler routeHandler=new Handler(Looper.getMainLooper());private AudioDeviceCallback deviceCallback;private Runnable routeTask;private final AudioRouting.OnRoutingChangedListener routeListener=output->routeHandler.post(this::verifyRoute);
public static boolean isPlaybackActive(){return live;}
