public void onCreate(){super.onCreate();live=false;origin="idle";playbackState(-1,"idle");NotificationChannel channel=new NotificationChannel(CHANNEL,"Solar alarm playback",NotificationManager.IMPORTANCE_LOW);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(channel);session=new MediaSession(this,"SolarElevationAlarm");session.setFlags(MediaSession.FLAG_HANDLES_MEDIA_BUTTONS|MediaSession.FLAG_HANDLES_TRANSPORT_CONTROLS);session.setCallback(new MediaSession.Callback(){public void onStop(){finish("Stopped");}public void onPause(){finish("Stopped by media Pause");}public void onSeekTo(long position){finish("Stopped by external seek");}public void onSkipToNext(){finish("Stopped by external skip");}public void onSkipToPrevious(){finish("Stopped by external skip");}public void onPlay(){}});session.setActive(true);}
private Notification notification(String title){Intent stop=new Intent(this,SolarAlarmPlaybackService.class).setAction("STOP").setData(Uri.parse("solar-stop://playback/"+token)).putExtra("playback_token",token);PendingIntent stopAction=PendingIntent.getService(this,1,stop,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent open=PendingIntent.getActivity(this,2,new Intent(this,SolarAlarmMainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);return new Notification.Builder(this,CHANNEL).setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle("Solar Elevation Alarm").setContentText(title).setOngoing(true).setContentIntent(open).addAction(new Notification.Action.Builder(android.R.drawable.ic_media_pause,"Stop",stopAction).build()).setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0)).build();}
