public int onStartCommand(Intent intent,int flags,int id){String action=intent==null?"STOP":intent.getAction();if("STOP".equals(action)){if(intent==null||!intent.hasExtra("playback_token")||intent.getLongExtra("playback_token",-1)==token)finish("Stopped");return START_NOT_STICKY;}boolean incomingAlarm="ALARM".equals(action);if(!incomingAlarm&&!"PREVIEW".equals(action)&&!"PLAY".equals(action)){stopSelfResult(id);return START_NOT_STICKY;}long event=intent.getLongExtra("event_id",-1);if(active>=0&&!incomingAlarm&&"scheduled alarm".equals(origin))return START_NOT_STICKY;SolarAlarmStore db=new SolarAlarmStore(this);SolarAlarmStore.Event e=db.get(event);db.close();if(e==null||e.uri.isEmpty()){if(active<0)stopSelfResult(id);return START_NOT_STICKY;}if(active>=0)releasePlayback(incomingAlarm?"Interrupted by scheduled alarm "+event:"Interrupted by manual audition "+event,false);active=event;activeEvent=e;restricted=SolarAlarmOutputRouteGuard.enabled(this);verified=false;routeChecks=0;live=true;origin=incomingAlarm?"scheduled alarm":"manual audition";playbackState(event,"preparing");long generation=++token;session.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,e.name).putString(MediaMetadata.METADATA_KEY_ARTIST,e.file).build());startForeground(8317,notification(e.name+" · preparing"));updateState(false);SolarAlarmOutputRouteGuard.event(this,"Audio start: "+origin+" event="+event+" restricted="+restricted);String problem=SolarAlarmOutputRouteGuard.prereq(this);if(problem!=null){finish("Audio blocked: "+problem);return START_NOT_STICKY;}try{SolarAlarmAudio.validate(this,e.uri,e.file);AudioAttributes attributes=new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build();audio=(AudioManager)getSystemService(AUDIO_SERVICE);focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(attributes).setOnAudioFocusChangeListener(change->{if(token==generation&&active==event&&(change==AudioManager.AUDIOFOCUS_LOSS||change==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT))routeHandler.post(()->finish("Stopped: audio focus lost"));}).build();if(audio.requestAudioFocus(focus)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED)throw new IOException("Audio focus denied");if(e.file.toLowerCase(Locale.ROOT).endsWith(".wv")){wavpack=new SolarAlarmWvPlayback(this,e.uri,restricted,new SolarAlarmWvPlayback.Listener(){public void onStarted(){routeHandler.post(()->{if(token!=generation||active!=event)return;AudioTrack t=wavpack==null?null:wavpack.getTrack();if(t!=null)t.addOnRoutingChangedListener(routeListener,routeHandler);if(restricted)startRouteChecks(generation);else started(generation,event,e);});}public void onFinished(String outcome){routeHandler.post(()->{if(token==generation&&active==event)finish(outcome);});}});wavpack.start();}else{player=new MediaPlayer();MediaPlayer p=player;p.setAudioAttributes(attributes);p.setWakeMode(this,PowerManager.PARTIAL_WAKE_LOCK);p.setVolume(restricted?0f:1f,restricted?0f:1f);p.setLooping(restricted);p.setDataSource(this,Uri.parse(e.uri));p.setOnPreparedListener(prepared->{if(active==event&&token==generation){try{if(restricted){AudioDeviceInfo device=SolarAlarmOutputRouteGuard.preferred(this);if(device==null)throw new IOException("No eligible output is connected");if(!prepared.setPreferredDevice(device))throw new IOException("Android refused preferred audio output");SolarAlarmOutputRouteGuard.event(this,"MediaPlayer preferred output: "+device.getProductName());}prepared.start();prepared.addOnRoutingChangedListener(routeListener,routeHandler);if(restricted)startRouteChecks(generation);else started(generation,event,e);}catch(Exception ex){finish("Audio blocked: "+ex.getMessage());}}});p.setOnCompletionListener(done->{if(token==generation)finish("Completed");});p.setOnErrorListener((failed,what,extra)->{if(token==generation)finish("Playback error: "+what+"/"+extra);return true;});p.prepareAsync();}}catch(Exception ex){finish("Playback error: "+ex.getMessage());}catch(LinkageError ex){finish("Native playback error: "+ex.getMessage());}return START_NOT_STICKY;}
private void startRouteChecks(long generation){if(!restricted||generation!=token||!live)return;deviceCallback=new AudioDeviceCallback(){public void onAudioDevicesAdded(AudioDeviceInfo[] list){routeHandler.post(()->verifyRoute());}public void onAudioDevicesRemoved(AudioDeviceInfo[] list){routeHandler.post(()->verifyRoute());}};if(audio!=null)audio.registerAudioDeviceCallback(deviceCallback,routeHandler);routeTask=new Runnable(){public void run(){if(token!=generation||!live||!restricted)return;verifyRoute();if(token==generation&&live&&restricted)routeHandler.postDelayed(this,150);}};routeHandler.post(routeTask);}
private void verifyRoute(){if(!live||!restricted)return;Object output=player!=null?player:wavpack==null?null:wavpack.getTrack();if(output==null)return;boolean allowed=SolarAlarmOutputRouteGuard.routed(output);if(allowed){if(!verified){try{if(player!=null){player.seekTo(0);player.setLooping(false);player.setVolume(1f,1f);}else if(wavpack!=null){wavpack.authorize();AudioTrack t=wavpack.getTrack();if(t!=null)t.setVolume(1f);}verified=true;SolarAlarmOutputRouteGuard.event(this,"Restricted route verified: "+SolarAlarmOutputRouteGuard.routeDetails(output));if(activeEvent!=null)started(token,active,activeEvent);}catch(Exception ex){finish("Audio blocked: verified output failed: "+ex.getMessage());}}}else if(verified){muteCurrent();finish("Audio blocked: output disconnected or no longer eligible");}else{routeChecks++;if(routeChecks==1||routeChecks%10==0)SolarAlarmOutputRouteGuard.event(this,"Waiting for restricted audio route: "+SolarAlarmOutputRouteGuard.routeDetails(output));if(routeChecks>=60)finish("Audio blocked: eligible output route could not be verified");}}
private void muteCurrent(){try{if(player!=null)player.setVolume(0f,0f);}catch(Exception ignored){}try{if(wavpack!=null&&wavpack.getTrack()!=null)wavpack.getTrack().setVolume(0f);}catch(Exception ignored){}}
