private synchronized void releasePlayback(String reason,boolean terminate){long previous=active;boolean wasRestricted=restricted;active=-1;activeEvent=null;live=false;origin="idle";playbackState(-1,"idle");token++;stopRouteChecks();muteCurrent();SolarAlarmWvPlayback w=wavpack;wavpack=null;if(w!=null)w.stop();MediaPlayer p=player;player=null;if(p!=null){try{p.stop();}catch(Exception ignored){}p.release();}updateState(false);AudioFocusRequest old=focus;focus=null;if(audio!=null&&old!=null)audio.abandonAudioFocusRequest(old);if(previous>=0){SolarAlarmStore s=new SolarAlarmStore(this);s.status(previous,reason);s.close();SolarAlarmOutputRouteGuard.event(this,"Audio ended: event="+previous+" restricted="+wasRestricted+" reason="+reason);}restricted=false;verified=false;routeChecks=0;if(terminate){stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();if(previous>=0&&reason.startsWith("Audio blocked:")){Notification note=new Notification.Builder(this,CHANNEL).setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle("Solar alarm audio blocked").setContentText(reason).setAutoCancel(true).build();((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(8321,note);}}}
